INSERT INTO wiki_pages (id, title, type, content) VALUES
('the-guide', 'The Guide', 'entity', '## Role Overview\n\nSubtle unfocused leadership. Does not dictate, but guides the overall vision and ensures all units are aligned with the core philosophy.'),
('head-of-operations', 'Head of Operations', 'entity', '## Role Overview\n\nHighest-ranking unit responsible for day-to-day operations and execution of the vision. Receives reports from the Visionary Lead and directs the Executive Director.'),
('visionary-lead', 'Visionary Lead', 'entity', '## Role Overview\n\nReports to the Head of Operations. Responsible for long-term planning, identifying new opportunities, and convening the Advisory Council when necessary.'),
('advisory-council', 'Advisory Council', 'entity', '## Role Overview\n\nAn external expert role convened by the Visionary Lead to provide specialized knowledge, feedback, and independent auditing.'),
('executive-director', 'Executive Director', 'entity', '## Role Overview\n\nNext in line under the Head of Operations. Coordinates technical execution and ensures the Chief Engineer has the necessary resources.'),
('chief-engineer', 'Chief Engineer', 'entity', '## Role Overview\n\nResponsible for coding and engineering assignments. Directs the Engineers and ensures technical standards are met.'),
('engineers', 'Engineers', 'entity', '## Role Overview\n\nJunior and Senior engineers assigned implementation work by the Chief Engineer. The builders of the system.'),
('archivists', 'Archivists', 'entity', '## Role Overview\n\nResponsible for the Wiki and verification layer. Ensures all knowledge is captured, categorized, and easily accessible.');
